async function retry(fn, times) {
  for (let attempt = 1; attempt <= times; attempt++) {
    try {
      return fn(attempt);
    } catch (error) {
      console.log("caught " + error.message);
    }
  }
}

const plain = (n) => {
  if (n < 2) throw new Error("plain " + n);
  return "plain ok";
};
const later = async (n) => {
  if (n < 2) throw new Error("async " + n);
  return "async ok";
};

retry(plain, 3).then((value) => console.log(value));
retry(later, 3).catch((error) => console.log("escaped: " + error.message));
